:root {
  --bg-card: #1a1a2e;
  --bg-controls: #16213e;
  --bg-meta: #0f3460;
  --accent-primary: #e94560;
  --accent-secondary: #f5a623;
  --progress-track: #2e2e4a;
  --progress-fill: #e94560;
  --text-primary: #ffffff;
  --text-secondary: #a0a8c0;
  --text-muted: #5c6380;
  --badge-bg: #e94560;
  --badge-text: #ffffff;
  --tag-bg: #0f3460;
  --tag-text: #f5a623;
  --speed-bg: #f5a623;
  --speed-text: #1a1a2e;
  --btn-play-bg: #e94560;
  --btn-play-text: #ffffff;
  --btn-skip-bg: #2e2e4a;
  --btn-skip-text: #a0a8c0;
  --border-subtle: #2e2e4a;
  --thumb-color: #ffffff;
}

.player-card {
  background-color: var(--bg-card);
  border-radius: 16px;
  padding: 20px;
  width: 460px;
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.episode-header {
  display: flex;
  align-items: center;
  gap: 10px;
}

.show-badge {
  background-color: var(--badge-bg);
  color: var(--badge-text);
  font-size: 11px;
  font-weight: 700;
  padding: 4px 10px;
  border-radius: 6px;
  letter-spacing: 0.08em;
}

.category-tag {
  background-color: var(--tag-bg);
  color: var(--tag-text);
  font-size: 11px;
  font-weight: 600;
  padding: 4px 10px;
  border-radius: 6px;
  letter-spacing: 0.04em;
}

.episode-title {
  color: var(--text-primary);
  font-size: 20px;
  font-weight: 700;
  line-height: 1.25;
  margin: 0;
}

.episode-desc {
  color: var(--text-secondary);
  font-size: 13px;
  line-height: 1.5;
  margin: 0;
}

.progress-section {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.progress-bar {
  position: relative;
  height: 6px;
  background-color: var(--progress-track);
  border-radius: 99px;
}

.progress-fill {
  position: absolute;
  top: 0;
  left: 0;
  height: 100%;
  width: 34%;
  background-color: var(--progress-fill);
  border-radius: 99px;
}

.progress-thumb {
  position: absolute;
  top: 50%;
  left: 34%;
  transform: translate(-50%, -50%);
  width: 14px;
  height: 14px;
  background-color: var(--thumb-color);
  border-radius: 50%;
}

.time-labels {
  display: flex;
  justify-content: space-between;
  color: var(--text-muted);
  font-size: 12px;
  font-weight: 500;
}

.controls {
  background-color: var(--bg-controls);
  border-radius: 12px;
  padding: 12px 16px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
}

.ctrl-btn {
  border: none;
  cursor: pointer;
  font-weight: 600;
  border-radius: 8px;
}

.skip-btn {
  background-color: var(--btn-skip-bg);
  color: var(--btn-skip-text);
  font-size: 12px;
  padding: 8px 14px;
}

.play-btn {
  background-color: var(--btn-play-bg);
  color: var(--btn-play-text);
  font-size: 18px;
  padding: 10px 22px;
  border-radius: 10px;
}

.speed-badge {
  background-color: var(--speed-bg);
  color: var(--speed-text);
  font-size: 12px;
  font-weight: 700;
  padding: 6px 10px;
  border-radius: 6px;
  margin-left: 4px;
}

.episode-meta {
  background-color: var(--bg-meta);
  border-radius: 10px;
  padding: 12px 16px;
  display: flex;
  justify-content: space-between;
}

.meta-item {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.meta-label {
  color: var(--text-muted);
  font-size: 10px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

.meta-value {
  color: var(--text-primary);
  font-size: 13px;
  font-weight: 600;
}
